        // --- チップ選択状態 ---
        const slAddSelected = { branch: null, category: null, shift: null };

        // --- チップ描画 ---
        function slRenderChips(containerId, items, selectedValue, groupKey) {
            var html = '';
            items.forEach(function(item) {
                var active = item === selectedValue ? ' md-ob-chip-active' : '';
                html += '<button type="button" class="md-ob-row-chip' + active + '" onclick="slSelectChip(\'' + groupKey + '\', \'' + escapeHtml(item) + '\')">' + escapeHtml(item) + '</button>';
            });
            document.getElementById(containerId).innerHTML = html;
        }

        function slSelectChip(groupKey, value) {
            if (slAddSelected[groupKey] === value) value = null;
            slAddSelected[groupKey] = value;
            if (groupKey === 'branch') slRenderChips('slAddBranchChips', slGetVisibleBranchList(), value, 'branch');
            else if (groupKey === 'category') {
                slRenderChips('slAddCategoryChips', slCategoryList, value, 'category');
                slAddRenderBadgeSection(value);
            }
            else if (groupKey === 'shift') slRenderChips('slAddShiftChips', slShiftList, value, 'shift');
            slUpdateWarnings();
            slUpdateHistoryBadges();
            slAutoOpenHistory();
        }

        // --- 警告表示 ---
        function slUpdateWarnings() {
            document.getElementById('slWarnBranch').style.display = slAddSelected.branch ? 'none' : '';
            document.getElementById('slWarnCategory').style.display = slAddSelected.category ? 'none' : '';
            document.getElementById('slWarnShift').style.display = slAddSelected.shift ? 'none' : '';
            var company = document.getElementById('slAddCompany').value.trim();
            document.getElementById('slWarnCompany').style.display = company ? 'none' : '';
            slUpdateSaveBtn();
        }

        function slUpdateSaveBtn() {
            var company = document.getElementById('slAddCompany').value.trim();
            var incomplete = !slAddSelected.branch || !slAddSelected.category || !slAddSelected.shift || !company;
            document.getElementById('slAddSaveBtn').disabled = incomplete;
        }

        // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
        // 新規追加モーダル: 信頼度チップ
        // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
        const slAddConfidenceOptions = [
            { value: 'confirmed',      label: '確定' },
            { value: 'tentative_high', label: '予定（高）' },
            { value: 'tentative_low',  label: '予定（低）' },
        ];
        let slAddSelectedConfidence = 'confirmed';

        function slAddRenderConfidenceChips(value) {
            slAddSelectedConfidence = value || 'confirmed';
            var container = document.getElementById('slAddConfidenceChips');
            var html = '';
            slAddConfidenceOptions.forEach(function(opt) {
                var active = opt.value === slAddSelectedConfidence ? ' md-ob-conf-active-' + opt.value : '';
                html += '<button type="button" class="md-ob-confidence-chip' + active + '" onclick="slAddSelectConfidence(\'' + opt.value + '\')">' + escapeHtml(opt.label) + '</button>';
            });
            container.innerHTML = html;
        }

        function slAddSelectConfidence(value) {
            slAddRenderConfidenceChips(value);
        }

        // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
        // 新規追加モーダル: 業務詳細（サブタスク）
        // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
        const slAddDefaultSubTaskPrefix = '工事名';

        function slAddAddSubTaskEntry() {
            var list = document.getElementById('slAddSubTaskList');
            var currentCount = list.children.length;
            var nums = ['①','②','③','④','⑤'];
            var num = nums[currentCount] || (currentCount + 1);
            var defaultLabel = slAddDefaultSubTaskPrefix + num;
            var idx = currentCount;
            var entry = document.createElement('div');
            entry.className = 'md-ob-sub-task-entry';
            entry.dataset.idx = idx;
            entry.innerHTML =
                '<input type="text" class="md-ob-sub-label-input" value="' + escapeHtml(defaultLabel) + '" placeholder="項目名" title="項目名を編集">' +
                '<input type="text" class="md-ob-sub-value-input" value="" placeholder="内容を入力">' +
                '<button type="button" class="btn btn-sm btn-icon btn-ghost btn-ghost--danger-hover" onclick="slAddRemoveSubTaskEntry(' + idx + ')" title="削除">×</button>';
            list.appendChild(entry);
            entry.querySelector('.md-ob-sub-value-input').focus();
        }

        function slAddRemoveSubTaskEntry(idx) {
            var list = document.getElementById('slAddSubTaskList');
            var entries = list.querySelectorAll('.md-ob-sub-task-entry');
            if (entries[idx]) {
                entries[idx].remove();
                list.querySelectorAll('.md-ob-sub-task-entry').forEach(function(entry, i) {
                    entry.dataset.idx = i;
                    entry.querySelector('.btn-ghost--danger-hover').setAttribute('onclick', 'slAddRemoveSubTaskEntry(' + i + ')');
                });
            }
        }

        function slAddCollectSubTasks() {
            var list = document.getElementById('slAddSubTaskList');
            var entries = list.querySelectorAll('.md-ob-sub-task-entry');
            var subTasks = [];
            entries.forEach(function(entry) {
                var label = entry.querySelector('.md-ob-sub-label-input').value.trim();
                var value = entry.querySelector('.md-ob-sub-value-input').value.trim();
                subTasks.push({ label: label || '項目', value: value });
            });
            return subTasks;
        }

        function slAddBuildSiteNameDisplay(task, subTasks) {
            var parts = [];
            if (task) parts.push(task);
            subTasks.forEach(function(st) {
                if (st.value) parts.push(st.value);
            });
            return parts.join(' ');
        }

        // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
        // 新規追加モーダル: 連絡チップ
        // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
        var slAddSelectedContact = null;

        function slAddRenderContactChips() {
            const container = document.getElementById('slAddContactChips');
            if (!container) return;
            let html = '';
            employeeContactItems.forEach(item => {
                const active = slAddSelectedContact === item.name ? ' md-ob-chip-active' : '';
                html += `<button type="button" class="md-ob-row-chip${active}" onclick="slAddSelectContact('${escapeHtml(item.name)}')">${escapeHtml(item.name)}</button>`;
            });
            container.innerHTML = html;
        }

        function slAddSelectContact(name) {
            slAddSelectedContact = slAddSelectedContact === name ? null : name;
            slAddRenderContactChips();
        }

        function slAddAddContact() {
            const name = prompt('新しい連絡項目名を入力:');
            if (!name || !name.trim()) return;
            const trimmed = name.trim();
            if (employeeContactItems.some(i => i.name === trimmed)) {
                alert('同名の項目が既に存在します。');
                return;
            }
            const colorPalette = [
                { bg: 'rgba(68,166,181,0.12)', color: '#2A6B7A', borderColor: 'rgba(68,166,181,0.3)' },
                { bg: 'rgba(56,161,105,0.12)', color: '#276749', borderColor: 'rgba(56,161,105,0.3)' },
                { bg: 'rgba(49,151,149,0.12)', color: '#285E61', borderColor: 'rgba(49,151,149,0.3)' },
                { bg: 'rgba(214,158,46,0.1)', color: '#975A16', borderColor: 'rgba(214,158,46,0.3)' },
                { bg: 'rgba(128,90,213,0.1)', color: '#6B46C1', borderColor: 'rgba(128,90,213,0.3)' }
            ];
            const idx = employeeContactItems.length % colorPalette.length;
            const colors = colorPalette[idx];
            const cssClass = 'contact-custom-' + employeeContactItems.length;
            employeeContactItems.push({
                name: trimmed, bg: colors.bg, color: colors.color,
                borderColor: colors.borderColor, cssClass: cssClass
            });
            slAddSelectedContact = trimmed;
            slAddRenderContactChips();
        }

        // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
        // 新規追加モーダル: 作業内容バッジ
        // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
        var slAddBadgeDefinitions = [
            { id: 'facility',        name: '施設',     children: [] },
            { id: 'event',           name: 'イベント', children: [] },
            { id: 'highway',         name: '高速',     children: [
                { id: 'hw-lane',     name: '車線規制', children: [
                    { id: 'hw-lane-sign',   name: '標識車' },
                    { id: 'hw-lane-mat',    name: '規制材' },
                    { id: 'hw-lane-light',  name: '保安灯' },
                ]},
                { id: 'hw-shoulder', name: '路肩規制', children: [
                    { id: 'hw-sh-cone', name: 'コーン' },
                    { id: 'hw-sh-bar',  name: 'バー' },
                ]},
                { id: 'hw-booth',    name: 'ブース規制', children: [] },
                { id: 'hw-security', name: '保安員', children: [] },
            ]},
            { id: 'traffic',         name: '交通',     children: [
                { id: 'tr-alternate', name: '片側交互', children: [
                    { id: 'tr-alt-flag', name: '旗' },
                    { id: 'tr-alt-sign', name: '看板' },
                ]},
                { id: 'tr-closure',   name: '通行止め', children: [] },
            ]},
            { id: 'support-traffic', name: '応援交通', children: [] },
        ];

        var slAddCategoryToBadgeId = {
            '施設': 'facility', 'イベント': 'event',
            '高速': 'highway', '交通': 'traffic', '応援交通': 'support-traffic',
        };

        var slAddSelectedParentBadge = null;
        var slAddSelectedChildBadges = [];
        var slAddSelectedGrandchildBadges = {};
        var slAddBadgeNextId = 1;

        function slAddGenerateBadgeId(prefix) {
            return prefix + '-sl-custom-' + (slAddBadgeNextId++);
        }

        function slAddRenderBadgeSection(category) {
            slAddSelectedParentBadge = slAddCategoryToBadgeId[category] || null;
            slAddSelectedChildBadges = [];
            slAddSelectedGrandchildBadges = {};
            slAddRenderChildBadges();
        }

        function slAddRenderChildBadges() {
            var container = document.getElementById('slAddBadgeChildList');
            var wrapper = document.getElementById('slAddBadgeChildSection');
            var hint = document.getElementById('slAddBadgeHint');
            if (!slAddSelectedParentBadge) {
                wrapper.style.display = 'none';
                if (hint) hint.style.display = '';
                return;
            }
            if (hint) hint.style.display = 'none';
            var parent = slAddBadgeDefinitions.find(function(p) { return p.id === slAddSelectedParentBadge; });
            if (!parent || parent.children.length === 0) {
                container.innerHTML = '<span class="md-ob-badge-empty">バッジなし</span>';
                wrapper.style.display = 'flex';
                return;
            }
            var html = '';
            parent.children.forEach(function(c, i) {
                var sel = slAddSelectedChildBadges.indexOf(c.id) >= 0 ? ' md-ob-badge-selected' : '';
                html += '<div class="md-ob-badge-drag-item" data-badge-idx="' + i + '" data-badge-id="' + c.id + '">';
                html += '<button type="button" class="md-ob-badge-chip md-ob-badge-child' + sel + '" onclick="slAddToggleChildBadge(\'' + c.id + '\')">' + escapeHtml(c.name) + '</button>';
                html += '</div>';
            });
            // 孫バッジセクション
            parent.children.forEach(function(c) {
                if (slAddSelectedChildBadges.indexOf(c.id) >= 0 && c.children && c.children.length > 0) {
                    html += slAddRenderGrandchildSection(c);
                }
            });
            container.innerHTML = html;
            wrapper.style.display = 'flex';
        }

        function slAddRenderGrandchildSection(childBadge) {
            var gcIds = slAddSelectedGrandchildBadges[childBadge.id] || [];
            var html = '<div class="md-ob-grandchild-section" data-child-id="' + childBadge.id + '">';
            html += '<div class="md-ob-grandchild-header">';
            html += '<span class="md-ob-grandchild-label">' + escapeHtml(childBadge.name) + ' <span class="md-ob-grandchild-arrow">›</span> 詳細</span>';
            html += '<button type="button" class="btn btn-sm btn-ghost btn-ghost--pill-dashed md-ob-gc-add" onclick="slAddAddGrandchildBadge(\'' + childBadge.id + '\')">+ 追加</button>';
            html += '</div>';
            if (childBadge.children) {
                childBadge.children.forEach(function(gc, i) {
                    var sel = gcIds.indexOf(gc.id) >= 0 ? ' md-ob-badge-selected' : '';
                    html += '<div class="md-ob-gc-drag-item" data-badge-idx="' + i + '">';
                    html += '<button type="button" class="md-ob-badge-chip md-ob-badge-grandchild' + sel + '" onclick="slAddToggleGrandchildBadge(\'' + childBadge.id + '\',\'' + gc.id + '\')">' + escapeHtml(gc.name) + '</button>';
                    html += '</div>';
                });
            }
            html += '</div>';
            return html;
        }

        function slAddToggleChildBadge(id) {
            var idx = slAddSelectedChildBadges.indexOf(id);
            if (idx >= 0) {
                slAddSelectedChildBadges.splice(idx, 1);
                delete slAddSelectedGrandchildBadges[id];
            } else {
                slAddSelectedChildBadges.push(id);
            }
            slAddRenderChildBadges();
        }

        function slAddToggleGrandchildBadge(childId, gcId) {
            if (!slAddSelectedGrandchildBadges[childId]) slAddSelectedGrandchildBadges[childId] = [];
            var arr = slAddSelectedGrandchildBadges[childId];
            var idx = arr.indexOf(gcId);
            if (idx >= 0) { arr.splice(idx, 1); } else { arr.push(gcId); }
            slAddRenderChildBadges();
        }

        function slAddAddChildBadge() {
            if (!slAddSelectedParentBadge) return;
            var name = prompt('新しい作業内容を入力:');
            if (!name || !name.trim()) return;
            var parent = slAddBadgeDefinitions.find(function(p) { return p.id === slAddSelectedParentBadge; });
            if (!parent) return;
            var id = slAddGenerateBadgeId('child');
            parent.children.push({ id: id, name: name.trim(), children: [] });
            slAddRenderChildBadges();
        }

        function slAddAddGrandchildBadge(childId) {
            var parent = slAddBadgeDefinitions.find(function(p) { return p.id === slAddSelectedParentBadge; });
            if (!parent) return;
            var child = parent.children.find(function(c) { return c.id === childId; });
            if (!child) return;
            var name = prompt('新しい詳細項目を入力:');
            if (!name || !name.trim()) return;
            if (!child.children) child.children = [];
            var id = slAddGenerateBadgeId('gc');
            child.children.push({ id: id, name: name.trim() });
            slAddRenderChildBadges();
        }

        function slAddGetSelectedBadgeData() {
            if (!slAddSelectedParentBadge) return null;
            return {
                parentId: slAddSelectedParentBadge,
                childIds: slAddSelectedChildBadges.slice(),
                grandchildMap: JSON.parse(JSON.stringify(slAddSelectedGrandchildBadges)),
            };
        }

        function slAddGetBadgeDisplayText(badge) {
            if (!badge || !badge.parentId) return '';
            var parent = slAddBadgeDefinitions.find(function(p) { return p.id === badge.parentId; });
            if (!parent) return '';
            var parts = [];
            if (badge.childIds && badge.childIds.length > 0) {
                badge.childIds.forEach(function(cid) {
                    var child = parent.children.find(function(c) { return c.id === cid; });
                    if (!child) return;
                    var gcMap = badge.grandchildMap || {};
                    var gcIds = gcMap[cid] || [];
                    if (gcIds.length > 0 && child.children) {
                        var gcNames = gcIds.map(function(gid) { return child.children.find(function(gc) { return gc.id === gid; }); })
                            .filter(Boolean).map(function(gc) { return gc.name; });
                        if (gcNames.length > 0) {
                            parts.push(child.name + ': ' + gcNames.join('・'));
                        } else {
                            parts.push(child.name);
                        }
                    } else {
                        parts.push(child.name);
                    }
                });
            }
            return parts.length > 0 ? parts.join('、') : '';
        }

        function slAddBuildBadgeDisplayHtml(badgeData) {
            if (!badgeData || !badgeData.parentId || !badgeData.childIds || badgeData.childIds.length === 0) return '';
            var parent = slAddBadgeDefinitions.find(function(p) { return p.id === badgeData.parentId; });
            if (!parent) return '';
            var html = '<div class="badge-display">';
            var gcMap = badgeData.grandchildMap || {};
            badgeData.childIds.forEach(function(childId, ci) {
                var child = parent.children.find(function(c) { return c.id === childId; });
                if (!child) return;
                if (ci > 0) html += '<span class="badge-group-sep"></span>';
                html += '<span class="badge-tag badge-child-tag">' + escapeHtml(child.name) + '</span>';
                var gcIds = gcMap[childId];
                if (gcIds && gcIds.length > 0 && child.children) {
                    html += '<span class="badge-gc-sep">\u203a</span>';
                    gcIds.forEach(function(gcId) {
                        var gc = child.children.find(function(g) { return g.id === gcId; });
                        if (gc) html += '<span class="badge-tag badge-gc-tag">' + escapeHtml(gc.name) + '</span>';
                    });
                }
            });
            html += '</div>';
            return html;
        }

        // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
        // 新規追加モーダル: 担当者候補
        // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
        var slAddSvCandidateList = [];
        var slAddSvDeletedCandidate = null;
        var slAddSvUndoTimer = null;

        // 契約先名×業務名の組み合わせで異なるダミー担当者データ
        var slAddSupervisorDb = [
            { company: '〇〇株式会社',           task: '〇〇ビル 巡回警備',   supervisors: [{ name: '山田太郎', tel: '080-9876-5432' }, { name: '山田太郎', tel: '090-1234-5678' }] },
            { company: '〇〇株式会社',           task: '〇〇ビル 夜間警備',   supervisors: [{ name: '山田太郎', tel: '' }, { name: '佐藤次郎', tel: '080-9876-5432' }] },
            { company: '(株)〇〇高速',           task: '東名SA巡回',          supervisors: [{ name: '鈴木三郎', tel: '070-1111-2222' }, { name: '鈴木三郎', tel: '090-1234-5678' }] },
            { company: '△△建設(株)',             task: '東名高速補修',        supervisors: [{ name: '佐藤次郎', tel: '' }] },
            { company: '□□警備(株)',             task: '国道1号線',            supervisors: [{ name: '高橋健一', tel: '090-5555-1234' }, { name: '山田太郎', tel: '090-1234-5678' }] },
            { company: '(株)丸山建設',           task: '〇〇ビル巡回',        supervisors: [{ name: '佐藤次郎', tel: '080-9876-5432' }, { name: '鈴木三郎', tel: '070-1111-2222' }, { name: '山田太郎', tel: '090-1234-5678' }] },
            { company: '全日本エンタープライズ', task: '商業施設A',            supervisors: [{ name: '高橋健一', tel: '090-5555-1234' }] },
        ];

        function slAddGetSupervisorCandidates(company, task) {
            if (!company && !task) return [];
            var results = [];
            var seen = {};
            // 完全一致 → 契約先のみ一致 → 業務名のみ一致の優先順で収集
            [function(r) { return r.company === company && r.task === task; },
             function(r) { return r.company === company; },
             function(r) { return r.task === task; }
            ].forEach(function(matchFn) {
                slAddSupervisorDb.forEach(function(row) {
                    if (!matchFn(row)) return;
                    row.supervisors.forEach(function(sv) {
                        var key = sv.name + '||' + sv.tel;
                        if (seen[key]) return;
                        seen[key] = true;
                        results.push({ name: sv.name, tel: sv.tel });
                    });
                });
            });
            return results;
        }

        function slAddUpdateSupervisorCandidates() {
            var company = document.getElementById('slAddCompany').value.trim();
            var task = document.getElementById('slAddTask').value.trim();
            slAddRenderSupervisorCandidates(company, task);
        }

        function slAddRenderSupervisorCandidates(company, task) {
            var container = document.getElementById('slAddSupervisorCandidates');
            slAddSvCandidateList = slAddGetSupervisorCandidates(company, task);
            if (slAddSvCandidateList.length === 0) {
                container.style.display = 'none';
                return;
            }
            slAddRenderSvChips();
            container.style.display = 'flex';
        }

        function slAddRenderSvChips() {
            var chipsEl = document.getElementById('slAddSupervisorCandidateChips');
            var html = '';
            slAddSvCandidateList.forEach(function(c, i) {
                var label = c.tel ? escapeHtml(c.name) + ' / ' + escapeHtml(c.tel) : escapeHtml(c.name);
                html += '<div class="md-ob-sv-drag-item" draggable="true" data-sv-idx="' + i + '">';
                html += '<span class="md-ob-sv-drag-grip">\u2630</span>';
                html += '<button type="button" class="md-ob-supervisor-chip" onclick="slAddSelectSupervisorCandidate(' + i + ')">' + label + '</button>';
                html += '<button type="button" class="md-ob-sv-delete-btn" onclick="slAddDeleteSupervisorCandidate(' + i + ')" title="削除">\u2715</button>';
                html += '</div>';
            });
            chipsEl.innerHTML = html;
            slAddInitSvDragDrop();
        }

        function slAddSelectSupervisorCandidate(idx) {
            if (!slAddSvCandidateList[idx]) return;
            document.getElementById('slAddSupervisor').value = slAddSvCandidateList[idx].name;
            document.getElementById('slAddSupervisorTel').value = slAddSvCandidateList[idx].tel;
        }

        function slAddDeleteSupervisorCandidate(idx) {
            var removed = slAddSvCandidateList.splice(idx, 1)[0];
            if (!removed) return;
            slAddSvDeletedCandidate = { candidate: removed, index: idx };
            slAddRenderSvChips();
            slAddShowSvUndoBar(removed.name);
            if (slAddSvCandidateList.length === 0) {
                document.getElementById('slAddSupervisorCandidates').style.display = 'none';
            }
        }

        function slAddShowSvUndoBar(name) {
            var bar = document.getElementById('slAddSvUndoBar');
            document.getElementById('slAddSvUndoMsg').textContent = '\u300c' + name + '\u300d\u3092\u524a\u9664\u3057\u307e\u3057\u305f';
            bar.style.display = 'flex';
            if (slAddSvUndoTimer) clearTimeout(slAddSvUndoTimer);
            slAddSvUndoTimer = setTimeout(function() {
                bar.style.display = 'none';
                slAddSvDeletedCandidate = null;
                slAddSvUndoTimer = null;
            }, 5000);
        }

        function slAddUndoDeleteSupervisor() {
            if (!slAddSvDeletedCandidate) return;
            slAddSvCandidateList.splice(slAddSvDeletedCandidate.index, 0, slAddSvDeletedCandidate.candidate);
            slAddSvDeletedCandidate = null;
            if (slAddSvUndoTimer) { clearTimeout(slAddSvUndoTimer); slAddSvUndoTimer = null; }
            document.getElementById('slAddSvUndoBar').style.display = 'none';
            document.getElementById('slAddSupervisorCandidates').style.display = 'flex';
            slAddRenderSvChips();
        }

        function slAddInitSvDragDrop() {
            var chipsEl = document.getElementById('slAddSupervisorCandidateChips');
            var dragSrcIdx = null;
            chipsEl.querySelectorAll('.md-ob-sv-drag-item').forEach(function(item) {
                item.addEventListener('dragstart', function(e) {
                    dragSrcIdx = parseInt(item.dataset.svIdx);
                    e.dataTransfer.effectAllowed = 'move';
                    item.classList.add('md-ob-sv-dragging');
                });
                item.addEventListener('dragend', function() {
                    item.classList.remove('md-ob-sv-dragging');
                    chipsEl.querySelectorAll('.md-ob-sv-drag-item').forEach(function(el) {
                        el.classList.remove('md-ob-sv-drag-over');
                    });
                });
                item.addEventListener('dragover', function(e) {
                    e.preventDefault();
                    e.dataTransfer.dropEffect = 'move';
                    item.classList.add('md-ob-sv-drag-over');
                });
                item.addEventListener('dragleave', function() {
                    item.classList.remove('md-ob-sv-drag-over');
                });
                item.addEventListener('drop', function(e) {
                    e.preventDefault();
                    var dropIdx = parseInt(item.dataset.svIdx);
                    if (dragSrcIdx === null || dragSrcIdx === dropIdx) return;
                    var moved = slAddSvCandidateList.splice(dragSrcIdx, 1)[0];
                    slAddSvCandidateList.splice(dropIdx, 0, moved);
                    slAddRenderSvChips();
                });
            });
        }

        // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
        // 新規追加モーダル: 地図エントリ管理
        // ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
        function slAddAddMapEntry() {
            var list = document.getElementById('slAddMapEntryList');
            var idx = list.children.length;
            var entry = document.createElement('div');
            entry.className = 'md-ob-map-entry';
            entry.dataset.idx = idx;
            entry.innerHTML =
                '<div class="md-ob-map-entry-header">' +
                    '<input type="text" class="md-ob-sub-label-input md-ob-map-label-input" value="" placeholder="タイトル" title="タイトルを編集">' +
                    '<button type="button" class="btn btn-sm btn-icon btn-ghost btn-ghost--danger-hover" onclick="slAddRemoveMapEntry(' + idx + ')" title="削除">×</button>' +
                '</div>' +
                '<div class="md-ob-map-url-row">' +
                    '<input type="url" class="md-ob-map-url-input" placeholder="Google Maps等のURLを入力">' +
                    '<button type="button" class="btn btn-sm btn-outline" onclick="slAddPreviewMap(this)">プレビュー</button>' +
                '</div>' +
                '<div class="md-ob-map-preview" style="display:none;">' +
                    '<iframe sandbox="allow-scripts allow-same-origin" loading="lazy"></iframe>' +
                    '<button type="button" class="btn btn-sm btn-icon btn-ghost" onclick="slAddClearMapPreview(this)" title="プレビューを閉じる">✕</button>' +
                '</div>';
            list.appendChild(entry);
            entry.querySelector('.md-ob-map-label-input').focus();
        }

        function slAddRemoveMapEntry(idx) {
            var list = document.getElementById('slAddMapEntryList');
            var entries = list.querySelectorAll('.md-ob-map-entry');
            if (entries[idx]) {
                entries[idx].remove();
                list.querySelectorAll('.md-ob-map-entry').forEach(function(entry, i) {
                    entry.dataset.idx = i;
                    entry.querySelector('.btn-ghost--danger-hover').setAttribute('onclick', 'slAddRemoveMapEntry(' + i + ')');
                });
            }
        }

        function slAddPreviewMap(btn) {
            var entry = btn.closest('.md-ob-map-entry');
            var url = entry.querySelector('.md-ob-map-url-input').value.trim();
            if (!url) return;
            var container = entry.querySelector('.md-ob-map-preview');
            var iframe = container.querySelector('iframe');
            iframe.src = url;
            container.style.display = 'block';
        }

        function slAddClearMapPreview(btn) {
            var container = btn.closest('.md-ob-map-preview');
            var iframe = container.querySelector('iframe');
            iframe.src = '';
            container.style.display = 'none';
        }

        function slAddCollectMapEntries() {
            var list = document.getElementById('slAddMapEntryList');
            var entries = list.querySelectorAll('.md-ob-map-entry');
            var maps = [];
            entries.forEach(function(entry) {
                var label = entry.querySelector('.md-ob-map-label-input').value.trim();
                var url = entry.querySelector('.md-ob-map-url-input').value.trim();
                if (label || url) maps.push({ label: label, url: url });
            });
            return maps;
        }

        function slAddResetMapEntries() {
            document.getElementById('slAddMapEntryList').innerHTML = '';
        }

        // --- 過去データアコーディオン ---
        let slHistorySelectedCompany = null;
        let slHistorySelectedTask = null;

        function slToggleHistory() {
            var panel = document.getElementById('slHistoryPanel');
            var icon = document.getElementById('slHistoryIcon');
            if (panel.style.display === 'none') {
                panel.style.display = '';
                icon.classList.add('md-ob-expanded');
                slUpdateHistoryBadges();
            } else {
                panel.style.display = 'none';
                icon.classList.remove('md-ob-expanded');
                slHistorySelectedCompany = null;
                slHistorySelectedTask = null;
            }
        }

        function slAutoOpenHistory() {
            if (slAddSelected.branch && slAddSelected.category) {
                var panel = document.getElementById('slHistoryPanel');
                if (panel.style.display === 'none') {
                    panel.style.display = '';
                    document.getElementById('slHistoryIcon').classList.add('md-ob-expanded');
                }
                slUpdateHistoryBadges();
            }
        }

        // 受注簿に該当レコードが存在するかチェック
        function slIsInOrderBook(branch, category, shift, company, task) {
            return slOrderBookRows.some(function(r) {
                return r.branch === branch && r.category === category
                    && (!shift || r.shift === shift)
                    && r.company === company && r.task === task;
            });
        }

        // 過去データからフィルタリング（DB全体）
        function slGetHistoryRecords(branch, category, shift) {
            return slHistoryDbRecords.filter(function(r) {
                if (r.branch !== branch) return false;
                if (r.category !== category) return false;
                if (shift && r.shift !== shift) return false;
                return true;
            });
        }

        function slUpdateHistoryBadges() {
            var panel = document.getElementById('slHistoryPanel');
            if (panel.style.display === 'none') return;

            var branch = slAddSelected.branch;
            var category = slAddSelected.category;
            var shift = slAddSelected.shift;

            if (!branch || !category) {
                document.getElementById('slHistoryHint').textContent = '会社と区分を選択してください';
                document.getElementById('slHistoryHint').style.display = '';
                document.getElementById('slHistoryCompanySection').style.display = 'none';
                document.getElementById('slHistoryTaskSection').style.display = 'none';
                return;
            }

            var records = slGetHistoryRecords(branch, category, shift);

            if (records.length === 0) {
                document.getElementById('slHistoryHint').textContent = '該当する過去データがありません';
                document.getElementById('slHistoryHint').style.display = '';
                document.getElementById('slHistoryCompanySection').style.display = 'none';
                document.getElementById('slHistoryTaskSection').style.display = 'none';
                return;
            }

            document.getElementById('slHistoryHint').style.display = 'none';
            document.getElementById('slHistoryCompanySection').style.display = '';

            // 契約先名のユニークリスト
            var companySet = {};
            records.forEach(function(r) { companySet[r.company] = true; });
            var companies = Object.keys(companySet);

            var html = '';
            companies.forEach(function(c) {
                var inOb = slIsInOrderBook(branch, category, shift, c, null) ||
                           slOrderBookRows.some(function(r) {
                               return r.branch === branch && r.category === category
                                   && (!shift || r.shift === shift) && r.company === c;
                           });
                var srcClass = inOb ? 'sl-hb-in-orderbook' : 'sl-hb-db-only';
                var active = c === slHistorySelectedCompany ? ' md-ob-hb-active' : '';
                html += '<button type="button" class="md-ob-history-badge ' + srcClass + active + '" onclick="slSelectHistoryCompany(\'' + escapeHtml(c).replace(/'/g, "\\'") + '\')">' + escapeHtml(c) + '</button>';
            });
            document.getElementById('slHistoryCompanyBadges').innerHTML = html;

            slUpdateHistoryTaskBadges(records);
        }

        function slUpdateHistoryTaskBadges(records) {
            if (!slHistorySelectedCompany) {
                document.getElementById('slHistoryTaskSection').style.display = 'none';
                return;
            }

            var branch = slAddSelected.branch;
            var category = slAddSelected.category;
            var shift = slAddSelected.shift;

            if (!records) records = slGetHistoryRecords(branch, category, shift);
            var filtered = records.filter(function(r) { return r.company === slHistorySelectedCompany; });

            var taskSet = {};
            filtered.forEach(function(r) { taskSet[r.task] = true; });
            var tasks = Object.keys(taskSet);

            if (tasks.length === 0) {
                document.getElementById('slHistoryTaskSection').style.display = 'none';
                return;
            }

            document.getElementById('slHistoryTaskSection').style.display = '';
            var html = '';
            tasks.forEach(function(t) {
                var inOb = slOrderBookRows.some(function(r) {
                    return r.branch === branch && r.category === category
                        && (!shift || r.shift === shift)
                        && r.company === slHistorySelectedCompany && r.task === t;
                });
                var srcClass = inOb ? 'sl-hb-in-orderbook' : 'sl-hb-db-only';
                var active = t === slHistorySelectedTask ? ' md-ob-hb-active' : '';
                var label = t || '(個別業務)';
                html += '<button type="button" class="md-ob-history-badge ' + srcClass + active + '" onclick="slSelectHistoryTask(\'' + escapeHtml(t).replace(/'/g, "\\'") + '\')">' + escapeHtml(label) + '</button>';
            });
            document.getElementById('slHistoryTaskBadges').innerHTML = html;
        }

        function slSelectHistoryCompany(company) {
            if (slHistorySelectedCompany === company) {
                slHistorySelectedCompany = null;
                slHistorySelectedTask = null;
            } else {
                slHistorySelectedCompany = company;
                slHistorySelectedTask = null;
                document.getElementById('slAddCompany').value = company;
                document.getElementById('slAddTask').value = '';
                slUpdateWarnings();
            }
            slUpdateHistoryBadges();
            slAddUpdateSupervisorCandidates();
        }

        function slSelectHistoryTask(task) {
            if (slHistorySelectedTask === task) {
                slHistorySelectedTask = null;
                document.getElementById('slAddTask').value = '';
            } else {
                slHistorySelectedTask = task;
                document.getElementById('slAddTask').value = task;
            }
            slUpdateHistoryBadges();
            slAddUpdateSupervisorCandidates();
        }

        // --- サジェスト ---
        function slGetCompanyList() {
            var set = {};
            slHistoryDbRecords.forEach(function(r) { set[r.company] = true; });
            slOrderBookRows.forEach(function(r) { if (r.company) set[r.company] = true; });
            // 現在のグリッドテーブルからも収集
            document.querySelectorAll('.grid-table tbody tr .company').forEach(function(el) {
                var t = el.textContent.trim();
                if (t) set[t] = true;
            });
            return Object.keys(set);
        }

        function slGetTaskList() {
            var set = {};
            slHistoryDbRecords.forEach(function(r) { if (r.task) set[r.task] = true; });
            slOrderBookRows.forEach(function(r) { if (r.task) set[r.task] = true; });
            document.querySelectorAll('.grid-table tbody tr .site-name').forEach(function(el) {
                var t = el.textContent.trim();
                if (t) set[t] = true;
            });
            return Object.keys(set);
        }

        function slCompanySuggest() {
            var input = document.getElementById('slAddCompany');
            var panel = document.getElementById('slCompanySuggestPanel');
            var val = input.value.trim();
            if (!val) { panel.style.display = 'none'; return; }

            var all = slGetCompanyList();
            var lower = val.toLowerCase();
            var prefix = [];
            var partial = [];
            all.forEach(function(c) {
                var cl = c.toLowerCase();
                if (cl.indexOf(lower) === 0) prefix.push(c);
                else if (cl.indexOf(lower) > 0) partial.push(c);
            });

            if (prefix.length === 0 && partial.length === 0) { panel.style.display = 'none'; return; }

            var html = '';
            if (prefix.length > 0) {
                html += '<div class="suggest-header">候補</div>';
                prefix.forEach(function(c) {
                    html += '<div class="suggest-item" onclick="slPickCompanySuggest(\'' + escapeHtml(c).replace(/'/g, "\\'") + '\')">' + escapeHtml(c) + '</div>';
                });
            }
            if (partial.length > 0) {
                html += '<div class="suggest-header">もしかして？</div>';
                partial.forEach(function(c) {
                    html += '<div class="suggest-item" onclick="slPickCompanySuggest(\'' + escapeHtml(c).replace(/'/g, "\\'") + '\')">' + escapeHtml(c) + '</div>';
                });
            }
            panel.innerHTML = html;
            panel.style.display = '';
        }

        function slPickCompanySuggest(val) {
            document.getElementById('slAddCompany').value = val;
            document.getElementById('slCompanySuggestPanel').style.display = 'none';
            slUpdateWarnings();
            slAddUpdateSupervisorCandidates();
        }

        function slTaskSuggest() {
            var input = document.getElementById('slAddTask');
            var panel = document.getElementById('slTaskSuggestPanel');
            var val = input.value.trim();
            if (!val) { panel.style.display = 'none'; return; }

            var all = slGetTaskList();
            var lower = val.toLowerCase();
            var prefix = [];
            var partial = [];
            all.forEach(function(t) {
                var tl = t.toLowerCase();
                if (tl.indexOf(lower) === 0) prefix.push(t);
                else if (tl.indexOf(lower) > 0) partial.push(t);
            });

            if (prefix.length === 0 && partial.length === 0) { panel.style.display = 'none'; return; }

            var html = '';
            if (prefix.length > 0) {
                html += '<div class="suggest-header">候補</div>';
                prefix.forEach(function(t) {
                    html += '<div class="suggest-item" onclick="slPickTaskSuggest(\'' + escapeHtml(t).replace(/'/g, "\\'") + '\')">' + escapeHtml(t) + '</div>';
                });
            }
            if (partial.length > 0) {
                html += '<div class="suggest-header">もしかして？</div>';
                partial.forEach(function(t) {
                    html += '<div class="suggest-item" onclick="slPickTaskSuggest(\'' + escapeHtml(t).replace(/'/g, "\\'") + '\')">' + escapeHtml(t) + '</div>';
                });
            }
            panel.innerHTML = html;
            panel.style.display = '';
        }

        function slPickTaskSuggest(val) {
            document.getElementById('slAddTask').value = val;
            document.getElementById('slTaskSuggestPanel').style.display = 'none';
            slAddUpdateSupervisorCandidates();
        }

        // --- モーダル開閉 ---
        function slOpenAddModal() {
            slAddSelected.branch = null;
            slAddSelected.category = null;
            slAddSelected.shift = null;
            slHistorySelectedCompany = null;
            slHistorySelectedTask = null;

            slRenderChips('slAddBranchChips', slGetVisibleBranchList(), null, 'branch');
            slRenderChips('slAddCategoryChips', slCategoryList, null, 'category');
            slRenderChips('slAddShiftChips', slShiftList, null, 'shift');

            document.getElementById('slAddCompany').value = '';
            document.getElementById('slAddTask').value = '';

            // サジェストパネルを閉じる
            document.getElementById('slCompanySuggestPanel').style.display = 'none';
            document.getElementById('slTaskSuggestPanel').style.display = 'none';

            // 過去データアコーディオンをリセット
            document.getElementById('slHistoryPanel').style.display = 'none';
            document.getElementById('slHistoryIcon').classList.remove('md-ob-expanded');
            document.getElementById('slHistoryCompanySection').style.display = 'none';
            document.getElementById('slHistoryTaskSection').style.display = 'none';

            // Placement / Details 初期化
            document.getElementById('slAddCount').value = '';
            slAddRenderConfidenceChips('confirmed'); // 確定をプリセット
            document.getElementById('slAddSubTaskList').innerHTML = '';

            // Category / Tasks 初期化
            slAddRenderBadgeSection(null);

            // Schedule / Notes 初���化
            document.getElementById('slAddStartTime').value = '';
            document.getElementById('slAddEndTime').value = '';
            document.getElementById('slAddSupervisor').value = '';
            document.getElementById('slAddSupervisorTel').value = '';
            slAddRenderSupervisorCandidates(null, null);
            document.getElementById('slAddMeetingPlace').value = '';
            document.getElementById('slAddMeetingTime').value = '';
            slAddSelectedContact = null;
            slAddRenderContactChips();
            slAddResetMapEntries();
            document.getElementById('slAddRemarks').value = '';

            document.getElementById('slAddModalOverlay').style.display = 'flex';
            slUpdateWarnings();
        }

        function slCloseAddModal(e) {
            if (e && e.target !== e.currentTarget) return;
            document.getElementById('slAddModalOverlay').style.display = 'none';
        }

        // --- 保存: 行追加 ---
        function slSaveNewRow() {
            var branch = slAddSelected.branch;
            var category = slAddSelected.category;
            var shift = slAddSelected.shift;
            var company = document.getElementById('slAddCompany').value.trim();
            var task = document.getElementById('slAddTask').value.trim();
            var timeStart = document.getElementById('slAddStartTime').value || '';
            var timeEnd = document.getElementById('slAddEndTime').value || '';
            var meetingPlace = document.getElementById('slAddMeetingPlace').value.trim();
            var meetingTime = document.getElementById('slAddMeetingTime').value || '';

            if (!branch || !category || !shift || !company) return;

            pushUndo();

            var gc = groupCompaniesData.find(function(g) { return g.name === branch; });
            var gcClass = gc ? gc.rowClass : '';
            var gcCode = gc ? gc.code : '';
            var shiftClass = slShiftClassMap[shift] || 'shift-day';
            var categoryClass = slCategoryClassMap[category] || 'category-facility';

            // テーブル行数を数えて番号を取得
            var tbody = document.querySelector('.grid-table tbody');
            var rowCount = tbody.querySelectorAll('tr').length;
            var no = rowCount + 1;

            var count = parseInt(document.getElementById('slAddCount').value) || 0;
            var countDisplay = '0/' + count;
            var shortage = count > 0;

            // 連絡バッジHTML生成
            var contactBadgeHtml = '';
            if (slAddSelectedContact) {
                var cItem = employeeContactItems.find(function(i) { return i.name === slAddSelectedContact; });
                if (cItem) {
                    contactBadgeHtml = '<span class="contact-badge contact-' + escapeHtml(cItem.cssClass || slAddSelectedContact.toLowerCase()) + '"'
                        + (cItem.bg ? ' style="background:' + cItem.bg + '; color:' + cItem.color + ';"' : '')
                        + '>' + escapeHtml(cItem.name) + '</span>';
                }
            }

            var tr = cnCreateRow({
                no: no,
                gcClass: gcClass,
                gcCode: gcCode,
                gcName: gc ? gc.name : branch,
                shiftClass: shiftClass,
                shiftLabel: shift,
                categoryClass: categoryClass,
                categoryLabel: category,
                company: company,
                siteName: slAddBuildSiteNameDisplay(task, slAddCollectSubTasks()),
                meetingTime: meetingTime,
                meetingMethod: meetingPlace ? '集合' : '',
                meetingMethodClass: meetingPlace ? 'contact-badge-meeting' : '',
                contactBadgeHtml: contactBadgeHtml,
                timeStart: timeStart,
                timeEnd: timeEnd,
                count: countDisplay,
                shortage: shortage
            });

            // 作業内容バッジをセルに反映
            var badgeData = slAddGetSelectedBadgeData();
            if (badgeData && badgeData.childIds && badgeData.childIds.length > 0) {
                var badgeTd = tr.querySelector('.col-badge');
                if (badgeTd) {
                    badgeTd.innerHTML = slAddBuildBadgeDisplayHtml(badgeData);
                }
            }

            // 地図データをセルに反映（URLがあるもののみ）
            var allMaps = slAddCollectMapEntries();
            var maps = allMaps.filter(function(m) { return m.url; });
            var mapTd = tr.querySelector('.col-map');
            if (mapTd) {
                if (maps.length > 0) {
                    mapTd.dataset.maps = JSON.stringify(maps);
                    mapTd.innerHTML = maps.map(function(m, i) {
                        return '<span class="map-tag">' + escapeHtml(m.label || '(無題)') + '</span>';
                    }).join('');
                }
                // maps.length === 0 の場合はcnCreateRowのデフォルト（＋）表示のまま
            }

            // 追加データを行の dataset に保存（モック用）
            tr.dataset.slOrigin = 'manual';
            tr.dataset.slAddConfidence = slAddSelectedConfidence;
            tr.dataset.slAddCount = count;
            tr.dataset.slAddSubTasks = JSON.stringify(slAddCollectSubTasks());
            tr.dataset.slAddBadge = JSON.stringify(badgeData);
            tr.dataset.slAddSupervisor = document.getElementById('slAddSupervisor').value;
            tr.dataset.slAddSupervisorTel = document.getElementById('slAddSupervisorTel').value;
            tr.dataset.slAddMeetingPlace = meetingPlace;
            tr.dataset.slAddContact = slAddSelectedContact || '';
            tr.dataset.slAddMaps = JSON.stringify(maps);
            tr.dataset.slAddRemarks = document.getElementById('slAddRemarks').value;

            insertBeforeFixedRows(tbody, tr);
            renumberRows();

            // 変更通知 (SL の行追加 = OB の受注追加に該当)
            var info = cnGetRowInfo(tr);
            if (info.siteName || company) {
                slCnSelfNotify('site', 'add', {
                    siteName: info.siteName || company,
                    category: category,
                    shift: shift,
                    company: company || info.company
                });
            }

            slCloseAddModal();
        }

        // サジェストパネルを外部クリックで閉じる
        document.addEventListener('click', function(e) {
            var cp = document.getElementById('slCompanySuggestPanel');
            var tp = document.getElementById('slTaskSuggestPanel');
            var scp = document.getElementById('smCompanySuggestPanel');
            var stp = document.getElementById('smTaskSuggestPanel');
            if (!e.target.closest('.md-ob-company-field')) {
                if (cp) cp.style.display = 'none';
                if (scp) scp.style.display = 'none';
            }
            if (!e.target.closest('.md-ob-task-field')) {
                if (tp) tp.style.display = 'none';
                if (stp) stp.style.display = 'none';
            }
        });
